import type { Locale } from './i18n';

export const RAW_TUTORIALS: Record<Locale, Record<string, string>> = {
  fr: {
    "blocs-force-musculation-cardio": "---\nslug: blocs-force-musculation-cardio\ntitle: Blocs Musculation et Cardio\nsummary: Ajouter des séries de force et des séries cardio à un WOD, et savoir ce qui compte dans les badges.\nrole: coach\npages: [whiteboard]\ntags: [musculation, force, cardio, series, badges, wod]\norder: 22\n---\n\n## Avant de commencer\n\nL'éditeur de WOD contient trois zones : **Programme / Mouvements** (le metcon), **Musculation** (optionnel) et **Cardio** (optionnel). Les deux blocs optionnels s'écrivent en séries, pas en reps libres.\n\n## Étapes\n\n1. Ouvre un WOD sur le Whiteboard et repère le bloc **Musculation (optionnel)**.\n2. Clique **Ajouter une série** puis remplis l'exercice, les séries, les reps et la charge — en kilos, en **%1RM**, ou en note libre du type `RPE 9` si la charge dépend du jour. Un **Tempo** (`30X1`) et un **Repos** peuvent compléter la ligne. <Screenshot src=\"/tutorials/blocs-force-musculation-cardio/1.png\" alt=\"Bloc Musculation avec une série, charge et tempo\" />\n3. Descends sur le bloc **Cardio (optionnel)** et clique **Ajouter une série cardio** : choisis le mouvement (Row, SkiErg, Run…), le nombre de séries et la quantité en mètres ou en calories.\n4. Ajoute une cible d'intensité si tu en veux une : **Watts** ou **Allure**, jamais les deux sur la même ligne. Le repos entre séries s'écrit en `mm:ss`.\n5. Publie le WOD : les trois blocs arrivent ensemble dans l'application de l'athlète, dans l'ordre où tu les as écrits.\n\n## Erreurs fréquentes\n\n- **Les séries de force ne créditent aucun badge.** C'est le comportement attendu : les séries du bloc Musculation ne comptent pas de reps de badge, ce n'est pas du metcon → mets au metcon ce qui doit compter.\n- **Une série cardio n'est pas créditée.** Le bloc Cardio, lui, est bien crédité en `séries × quantité`, mais seulement si le mouvement vient du catalogue → choisis Row, SkiErg, Run… dans la liste.\n- **Une cible d'allure est ignorée.** Des watts ET une allure ont été saisis sur la même ligne → n'en garde qu'un des deux.\n- **La charge « RPE 9 » disparaît du champ kilos.** Une charge non numérique n'est pas un poids : elle se saisit en note de charge → utilise le champ de note libre.\n\n## Y aller\n\n<GoTo page=\"whiteboard\" />\n",
    "creer-un-wod": "---\nslug: creer-un-wod\ntitle: Créer un WOD\nsummary: Programmer une séance sur le Whiteboard : titre, date, mouvements, charges, puis publication.\nrole: coach\npages: [whiteboard]\ntags: [wod, whiteboard, mouvements, charges, programmation]\norder: 20\n---\n\n## Avant de commencer\n\nLe **Whiteboard** (Entraînement → Whiteboard) affiche la semaine courante, un jour par colonne. Un WOD appartient à un jour et à une heure de publication ; tu peux le préparer à l'avance sans qu'il soit visible.\n\n## Étapes\n\n1. Sur le Whiteboard, place-toi sur la bonne semaine avec les flèches ou **Aller à une date**, puis clique **Nouveau WOD** (ou directement dans la case d'un jour vide). <Screenshot src=\"/tutorials/creer-un-wod/1.png\" alt=\"Whiteboard de la semaine avec le bouton Nouveau WOD\" />\n2. Remplis l'en-tête : **Titre** (par exemple « Fran », « Intervalles Hybrid »), **Date**, **Heure**, **Type** et **Block** si tu utilises ces repères. L'heure indiquée est celle à laquelle le WOD devient visible le jour programmé.\n3. Dans **Programme / Mouvements**, saisis une ligne par mouvement : reps, exercice choisi dans la liste, puis les charges hommes et femmes. Choisir l'exercice dans la liste est ce qui garantit le comptage des badges de tes athlètes.\n4. Ajoute si besoin les notes de séance dans **Notes Coach** (scaling, consignes) et une **Vidéo YouTube** de démonstration. <Screenshot src=\"/tutorials/creer-un-wod/2.png\" alt=\"Éditeur de WOD : titre, mouvements et charges\" />\n5. Choisis l'audience dans **Qui reçoit ce WOD ?** : « Toute la box », « Ces groupes » ou « Personne encore ».\n6. Clique **Publier**. Le WOD apparaît dans la case du jour ; un clic sur la carte le rouvre pour le modifier.\n\n## Erreurs fréquentes\n\n- **Le WOD est créé mais aucun athlète ne le voit.** L'audience est restée sur « Personne encore » → rouvre le WOD et choisis « Toute la box » ou les groupes concernés.\n- **Impossible de valider avec « Ces groupes ».** Aucun groupe n'est coché, l'éditeur affiche « Coche au moins un groupe. » → coche les groupes, ou repasse sur « Toute la box ».\n- **Les badges des athlètes ne bougent pas après la séance.** Le mouvement a été tapé librement au lieu d'être choisi dans la liste → réédite la ligne et sélectionne l'exercice du catalogue.\n- **Le crayon de la carte est inactif.** Cette séance vient d'une programmation Marketplace : son contenu n'est pas modifiable, seule l'audience l'est.\n\n## Y aller\n\n<GoTo page=\"whiteboard\" />\n",
    "creneaux-et-reservations": "---\nslug: creneaux-et-reservations\ntitle: Créneaux et réservations\nsummary: Créer les cours de la semaine, fixer la capacité et faire l'appel.\nrole: owner\npages: [schedule]\ntags: [creneaux, horaires, reservations, capacite, appel, coach]\norder: 32\n---\n\n## Avant de commencer\n\n**Horaires & Créneaux** (Entraînement → Horaires) contient les cours réservables de la box, jour par jour. Les modèles de semaine se gèrent à côté, dans Créneaux types.\n\n## Étapes\n\n1. Ouvre **Horaires & Créneaux** et place-toi sur le jour visé.\n2. Clique pour ajouter un créneau et remplis-le : **Type de cours** (ou un **Nom personnalisé**), **Début**, durée, **Capacité** et éventuellement une **Description**. <Screenshot src=\"/tutorials/creneaux-et-reservations/1.png\" alt=\"Formulaire de création d'un créneau\" />\n3. Assigne un **Coach (optionnel)** : il apparaît côté athlète et permet à tes coachs de se repérer.\n4. Enregistre : le créneau devient réservable par les membres, dans la limite de la capacité.\n5. Le jour du cours, ouvre le créneau et clique **Faire l'appel** pour voir les inscrits et marquer les présences. Tu peux aussi **Ajouter un membre** à la main si quelqu'un arrive sans réservation.\n\n## Erreurs fréquentes\n\n- **« Aucun coach assigné à cette box. »** Aucun coach n'est enregistré dans Réglages → ajoute-le, puis reviens assigner le créneau.\n- **Un membre ne peut pas réserver.** La capacité est atteinte, ou le créneau est passé → augmente la capacité ou ouvre un second créneau.\n- **« Aucun inscrit pour ce créneau » alors que le cours est plein.** Tu regardes un autre jour ou un autre créneau du même type → vérifie la date affichée en haut.\n- **Les créneaux de la semaine prochaine sont absents.** Ils se génèrent depuis les Créneaux types → ouvre cette page pour poser la grille récurrente.\n\n## Y aller\n\n<GoTo page=\"schedule\" />\n",
    "groupes-de-membres": "---\nslug: groupes-de-membres\ntitle: Groupes de membres\nsummary: Créer des groupes et y placer des membres pour cibler la programmation et les créneaux.\nrole: owner\npages: [members, groups]\ntags: [groupes, membres, ciblage, audience]\norder: 30\n---\n\n## Avant de commencer\n\nUn **groupe** rassemble des membres (un niveau, un créneau, un suivi particulier). Il sert d'audience aux WODs et de filtre dans la liste des membres. Les groupes se gèrent dans Communauté → Groupes.\n\n## Étapes\n\n1. Ouvre **Groupes** et clique **Nouveau groupe** : donne-lui un nom clair pour un coach pressé (« Compétiteurs », « Midi », « Débutants »). <Screenshot src=\"/tutorials/groupes-de-membres/1.png\" alt=\"Liste des groupes de la box\" />\n2. Enregistre, puis ouvre le groupe pour y **Ajouter un membre** ; la recherche porte sur les membres actifs de la box.\n3. Va dans **Membres** pour vérifier le résultat : le filtre **Tous les groupes** permet de n'afficher qu'un groupe à la fois.\n4. Utilise ensuite le groupe comme audience : dans un WOD, choisis **Ces groupes** et coche-le.\n\n## Erreurs fréquentes\n\n- **« Aucun groupe. Crée des groupes de cours d'abord. »** Le sélecteur d'audience reste vide tant qu'aucun groupe n'existe → crée-en un dans Groupes.\n- **Un membre ne reçoit pas les WODs du groupe.** Il n'a jamais été ajouté au groupe, ou son compte n'est plus actif → vérifie sa fiche dans Membres.\n- **Un groupe supprimé laisse des WODs sans public.** Les séances ciblées sur ce groupe ne trouvent plus personne → rouvre-les et choisis une autre audience.\n\n## Y aller\n\n<GoTo page=\"groups\" />\n",
    "importer-un-pdf-de-programmation": "---\nslug: importer-un-pdf-de-programmation\ntitle: Importer un PDF de programmation\nsummary: Transformer un PDF de semaine en WODs ou en séances de programme, en relisant l'écran de preview.\nrole: coach\npages: [whiteboard, programs]\ntags: [pdf, import, programmation, preview, notes coach]\norder: 24\n---\n\n## Avant de commencer\n\nL'import PDF lit un document de programmation et propose des séances prêtes à insérer : sur le **Whiteboard** pour la semaine de la box, ou dans l'éditeur de séances d'un **Programme athlète**. L'analyse est une proposition, jamais un enregistrement direct.\n\n## Étapes\n\n1. Depuis le Whiteboard, ouvre l'import et dépose ton fichier — tu peux aussi le glisser directement sur la page, qui affiche « Lâche ton fichier pour l'importer ».\n2. Attends la fin de l'**Analyse du PDF…**. L'écran de preview liste chaque séance détectée avec ses mouvements, son bloc **Musculation** et ses **Notes coach**. <Screenshot src=\"/tutorials/importer-un-pdf-de-programmation/1.png\" alt=\"Écran de preview de l'import PDF avec les séances détectées\" />\n3. Relis ligne par ligne. Les champs surlignés portent l'avertissement **Mouvement hors catalogue** : corrige-les en choisissant l'exercice de la liste, ou laisse le nom brut en connaissance de cause.\n4. Choisis l'audience dans **Qui verra ces WOD** (ou **Qui verra ces séances** pour un programme athlète) : toute la box, des groupes, ou personne pour l'instant.\n5. Valide l'insertion. Les séances arrivent sur les jours détectés et restent modifiables comme n'importe quel WOD.\n\n## Erreurs fréquentes\n\n- **« Aucun WOD détecté dans ce PDF. »** Le document est une image scannée ou une mise en page que l'analyse ne reconnaît pas → saisis la semaine à la main, ou repasse par un PDF texte.\n- **Les charges en RPE ou en % du RM ont disparu des champs de poids.** Une charge non numérique n'est pas un kilo : elle part en note de charge ou en notes coach → vérifie-la dans la preview avant d'insérer.\n- **Des mouvements sont surlignés en orange.** Ils sont hors catalogue et seront conservés tels quels, donc sans badge → remplace-les par une entrée de la liste.\n- **Les séances importées ne sont visibles par personne.** L'audience choisie dans la preview était « personne encore » → rouvre chaque séance et fixe son audience.\n\n## Y aller\n\n<GoTo page=\"whiteboard\" />\n",
    "marketplace-appliquer-au-whiteboard": "---\nslug: marketplace-appliquer-au-whiteboard\ntitle: Appliquer une programmation au Whiteboard\nsummary: Poser une semaine d'une programmation souscrite, comprendre l'ancrage des semaines et ce qui reste modifiable.\nrole: both\npages: [whiteboard]\ntags: [marketplace, programmation, whiteboard, ancrage, cron, audience]\norder: 51\n---\n\n## Avant de commencer\n\nUne fois la box abonnée, les semaines d'une programmation se posent sur le Whiteboard : automatiquement si tu l'as demandé, sinon à la main depuis le bouton **Programmation**.\n\n## Étapes\n\n1. Sur le Whiteboard, clique **Programmation**. La modale liste **Mes semaines types** puis **Programmations Marketplace** avec tes abonnements actifs (offre, box qui publie, nombre de WOD et de semaines). <Screenshot src=\"/tutorials/marketplace-appliquer-au-whiteboard/1.png\" alt=\"Modale Programmation avec un abonnement Marketplace sélectionné\" />\n2. Sélectionne l'abonnement à poser : il se surligne et les champs de pose apparaissent.\n3. Choisis la **Semaine source** (la semaine de la programmation, avec son nombre de WOD) et la **Semaine cible** (le lundi à partir duquel les séances se posent). La modale rappelle la date exacte retenue.\n4. Choisis l'audience dans **Qui voit ces WOD ?** : **Toute la box**, **Ces groupes** ou **Personne encore**. Ce choix devient aussi la visibilité par défaut de l'application automatique de cet abonnement.\n5. Clique **Appliquer**. Les séances arrivent sur les jours de la semaine cible, à la couleur de l'abonnement ; celles qui portent déjà un score ou une complétion ne sont pas remplacées.\n6. Ajuste ensuite carte par carte : l'audience reste la tienne, et une séance reçue peut être déplacée ou supprimée individuellement.\n\n## Erreurs fréquentes\n\n- **Les semaines automatiques n'arrivent pas au bon moment.** Avec l'application automatique, la semaine due se pose le dimanche à 18h pour la semaine qui suit ; poser une semaine à la main réaligne l'ancrage sur ce que tu viens de faire. {/* TODO Nab: vérifier libellé — la spec parle du lundi suivant l'abonnement, l'écran Marketplace annonce le dimanche 18h */}\n- **Une séance reçue refuse d'être modifiée.** Son contenu appartient à la programmation : il n'est pas modifiable. Tu peux la supprimer, carte par carte, ou changer son audience.\n- **Personne ne voit les séances posées.** L'audience est restée sur « Personne encore », ce qui est le cas par défaut des poses automatiques → fixe l'audience.\n- **La modale ne propose aucune programmation.** `Programmations Marketplace` affiche `Aucun abonnement actif` : la box n'est abonnée à rien → passe par Entraînement → Marketplace.\n- **Une semaine type posée n'est pas une offre Marketplace.** Le haut de la modale (`Mes semaines types`) pose tes propres modèles ; ça ne crée ni abonnement ni offre publiée.\n\n## Y aller\n\n<GoTo page=\"whiteboard\" />\n",
    "marketplace-publier-une-offre": "---\nslug: marketplace-publier-une-offre\ntitle: Publier une offre sur la Marketplace\nsummary: Créer une programmation, la remplir semaine par semaine et la publier dans le catalogue.\nrole: owner\npages: [marketplace, whiteboard]\ntags: [marketplace, offre, publication, vente, semaines]\norder: 52\n---\n\n## Avant de commencer\n\nPublier une offre, c'est proposer ta programmation aux autres box. L'onglet **Mes offres** de la Marketplace contient tes programmations publiées ou en préparation.\n\n## Étapes\n\n1. Ouvre **Marketplace**, onglet **Mes offres**, et crée une programmation : titre, description, objectif, public visé, discipline, niveau, **WOD par semaine** et facturation. <Screenshot src=\"/tutorials/marketplace-publier-une-offre/1.png\" alt=\"Onglet Mes offres de la Marketplace\" />\n2. Remplis ses semaines. Le plus rapide : depuis le Whiteboard, affiche une semaine réussie et clique **Copier vers une offre**, puis choisis l'offre et le numéro de semaine.\n3. Vérifie le contenu semaine par semaine. L'écran signale une offre dont la semaine 1 est vide.\n4. Clique sur le bouton de publication de l'offre : elle rejoint le **Catalogue** et devient visible des autres box.\n5. Si tu gères plusieurs box, tu peux aussi **diffuser à tes boxs** en décochant celles à exclure.\n\n## Erreurs fréquentes\n\n- **« Publication refusée ».** Une offre sans WOD ne se publie pas et n'apparaît pas dans le catalogue → remplis au moins la semaine 1, puis republie.\n- **« J'ai enregistré une semaine type, l'offre est restée vide. »** Une semaine type est interne à ta box : elle n'alimente pas une offre → utilise **Copier vers une offre**.\n- **Les box abonnées ne voient pas ma correction.** Les copies sont indépendantes : modifier une semaine d'offre ne réécrit pas ce qui a déjà été reçu → préviens tes abonnées, ou corrige la semaine suivante.\n- **Mon offre n'apparaît pas dans mon propre catalogue.** C'est volontaire : on ne s'abonne pas à ses propres offres → vérifie-la depuis l'onglet Mes offres.\n\n## Y aller\n\n<GoTo page=\"marketplace\" />\n",
    "marketplace-s-abonner-a-une-programmation": "---\nslug: marketplace-s-abonner-a-une-programmation\ntitle: S'abonner à une programmation Marketplace\nsummary: Trouver une programmation publiée par une autre box, s'y abonner et régler l'application automatique.\nrole: owner\npages: [marketplace, whiteboard]\ntags: [marketplace, abonnement, programmation, catalogue, application automatique]\norder: 50\n---\n\n## Avant de commencer\n\nLa **Marketplace** (Entraînement → Marketplace) est le circuit box vers box : tu y achètes ou vends des programmations. Ce que tu reçois arrive dans ton Whiteboard. La page est réservée au gérant et aux coachs.\n\n## Étapes\n\n1. Ouvre **Marketplace**, onglet **Catalogue**, et filtre par discipline, niveau ou **Gratuit** pour parcourir les offres publiées par les autres box. Chaque carte indique la box qui publie, l'objectif, le nombre de WOD et la durée. <Screenshot src=\"/tutorials/marketplace-s-abonner-a-une-programmation/1.png\" alt=\"Catalogue Marketplace avec les filtres et une offre\" />\n2. Clique **Voir le détail** : tu vois l'objectif, le **public visé**, le **matériel**, les **WOD par semaine**, la facturation (**Mensuel**, **Paiement unique** ou **Gratuit**) et l'**Aperçu de la semaine 1**, jour par jour. <Screenshot src=\"/tutorials/marketplace-s-abonner-a-une-programmation/2.png\" alt=\"Détail d'une offre Marketplace avec l'aperçu de la semaine 1\" />\n3. Clique **S'abonner**. Le bouton devient **Abonné** et la carte affiche les réglages de l'abonnement. Tes propres offres ne sont pas proposées à l'abonnement.\n4. Choisis la **Couleur** : c'est elle qui identifiera les séances de cette programmation sur le Whiteboard. <Screenshot src=\"/tutorials/marketplace-s-abonner-a-une-programmation/3.png\" alt=\"Offre à l'état Abonné avec la couleur, l'application automatique et Se désabonner\" />\n5. Décide du mode de pose. Rien ne se pose tout seul tant que **Application automatique chaque semaine** n'est pas cochée ; cochée, la semaine due se pose seule le dimanche à 18h, la semaine 1 le premier dimanche. Décochée, tu poses les semaines quand tu veux depuis le Whiteboard, bouton **Programmation**.\n6. Pour arrêter, **Se désabonner** sur la même carte : une confirmation propose de **retirer aussi les séances déjà posées à partir de la semaine prochaine**. La semaine en cours et le passé ne sont jamais supprimés, les scores et l'ELO sont conservés.\n\n## Erreurs fréquentes\n\n- **Rien n'arrive dans le Whiteboard après l'abonnement.** L'application automatique est décochée — c'est le réglage par défaut → pose la semaine depuis le Whiteboard, ou coche la case.\n- **Les séances reçues ne sont vues par aucun membre.** Les poses automatiques arrivent en « Personne encore » → ouvre-les et choisis leur audience.\n- **Impossible de modifier une séance reçue.** Le contenu d'une programmation Marketplace n'est pas modifiable ; tu choisis seulement qui la voit, et tu peux la déplacer ou la supprimer.\n- **« déjà abonnée ».** Une autre de tes box est déjà abonnée à cette offre → vérifie la box active dans le sélecteur en haut de la barre latérale.\n\n## Y aller\n\n<GoTo page=\"marketplace\" />\n",
    "membres-et-formules": "---\nslug: membres-et-formules\ntitle: Membres, contrats et formules\nsummary: Suivre les membres de la box, leurs contrats et l'accès qu'ils ont à tes offres.\nrole: owner\npages: [members]\ntags: [membres, contrats, abonnements, formules, invitation]\norder: 31\n---\n\n## Avant de commencer\n\nLes membres rejoignent la box avec le **code invitation** du Dashboard. La page **Membres** (Communauté → Membres) liste ensuite tout le monde, avec la recherche, les filtres et l'accès aux contrats.\n\n## Étapes\n\n1. Ouvre **Membres** : le compteur du haut indique le nombre de fiches affichées sur le total, et la recherche accepte un nom ou un e-mail. <Screenshot src=\"/tutorials/membres-et-formules/1.png\" alt=\"Liste des membres avec la recherche et les filtres\" />\n2. Affine avec les filtres : par groupe, ou par état de contrat, pour retrouver par exemple les membres sans abonnement.\n3. Clique **Contrats** pour afficher la colonne **Contrats / Abonnements** : tu vois d'un coup d'œil quelle formule chaque membre détient et jusqu'à quand.\n4. Ouvre une fiche membre pour son détail : groupes, ELO, historique. C'est aussi d'ici que tu vérifies qu'un membre est bien actif.\n5. Les formules elles-mêmes (prix, durée, engagement) se créent dans **Programmes athlètes** : la page Membres les consomme, elle ne les définit pas.\n\n## Erreurs fréquentes\n\n- **Un adhérent n'apparaît pas dans la liste.** Il n'a pas encore rejoint la box avec le code invitation → renvoie-lui le code depuis le Dashboard.\n- **Un membre dit payer mais n'a aucun contrat.** Le paiement a été fait hors AthleX, ou la souscription n'a pas abouti → vérifie la colonne Contrats et, si besoin, donne-lui l'accès depuis Programmes athlètes.\n- **Impossible de créer une formule depuis Membres.** C'est normal : la création et l'édition des formules vivent dans Programmes athlètes → ouvre cette page.\n- **Un coach ne voit pas la page Membres.** Elle est réservée au gérant → connecte-toi avec le compte owner.\n\n## Y aller\n\n<GoTo page=\"members\" />\n",
    "mouvements-et-badges": "---\nslug: mouvements-et-badges\ntitle: Mouvements et badges\nsummary: Pourquoi choisir les exercices dans la liste officielle, et ce qui crédite les badges des athlètes.\nrole: coach\npages: [whiteboard]\ntags: [mouvements, catalogue, badges, reps, whiteboard]\norder: 23\n---\n\n## Avant de commencer\n\nLes badges de mouvement des athlètes se calculent sur les reps effectuées, mouvement par mouvement. Le rattachement se fait par le **catalogue officiel** proposé dans l'éditeur de WOD, pas par le texte saisi.\n\n## Étapes\n\n1. Dans un WOD, place-toi sur une ligne de **Programme / Mouvements** et commence à taper dans le champ d'exercice : la liste se filtre à la frappe. <Screenshot src=\"/tutorials/mouvements-et-badges/1.png\" alt=\"Recherche d'un mouvement dans la liste officielle\" />\n2. Sélectionne l'entrée proposée par la liste, même si son nom diffère un peu de ton habitude — c'est ce choix qui relie la ligne au mouvement suivi par l'app.\n3. Renseigne les reps et les charges hommes / femmes : le badge se calcule sur les reps, les charges servent à l'athlète et au classement.\n4. Répète pour chaque ligne du metcon, puis publie. Après la séance, les reps validées par les athlètes alimentent leurs badges sans action de ta part.\n\n## Erreurs fréquentes\n\n- **Un mouvement écrit à la main ne donne aucun badge.** Hors catalogue, il est enregistré avec son nom brut et ne crédite rien → réédite la ligne et prends l'entrée de la liste.\n- **Les reps du bloc Musculation ne comptent pas.** Les séries de force ne sont pas du metcon : elles ne créditent pas de badge, contrairement au bloc Cardio qui est crédité en `séries × quantité`.\n- **Un mouvement manque dans la liste.** Le catalogue est commun à la plateforme et n'est pas modifiable depuis la box → écris-le en clair pour la séance et signale-le à AthleX pour qu'il soit ajouté.\n- **Deux variantes du même mouvement donnent des compteurs différents.** Ce sont deux entrées distinctes du catalogue → garde la même entrée d'une séance à l'autre.\n\n## Y aller\n\n<GoTo page=\"whiteboard\" />\n",
    "premiers-pas": "---\nslug: premiers-pas\ntitle: Premiers pas dans AthleX Manager\nsummary: Ce qu'il faut régler le premier jour pour que la box tourne : identité, coachs, code d'invitation.\nrole: both\npages: [dashboard]\ntags: [demarrage, dashboard, reglages, invitation, coach]\norder: 10\n---\n\n## Avant de commencer\n\nTu viens de créer ta box : le Dashboard est la page d'accueil du back-office, et la barre latérale regroupe les rubriques par casquette (Entraînement, Communauté, Animation, Business). Compte cinq minutes pour cette mise en route.\n\n## Étapes\n\n1. Ouvre le **Dashboard** : les compteurs du haut (membres, réservations, tournois, messages non lus) sont des raccourcis, pas de simples chiffres — un clic ouvre la rubrique correspondante. <Screenshot src=\"/tutorials/premiers-pas/1.png\" alt=\"Dashboard avec les compteurs de la box\" />\n2. Va dans **Réglages** et remplis les **Informations de la box** : nom, logo, bannière. Ce sont les éléments que voient tes membres et les visiteurs de ta page publique.\n3. Toujours dans **Réglages**, ajoute tes **Coachs**. Un coach voit le Whiteboard, les Horaires, les Créneaux types, les Messages et l'Aide ; il ne voit ni les prix ni les abonnés.\n4. Récupère le **code invitation** depuis le Dashboard et transmets-le à tes adhérents : c'est par lui qu'ils rejoignent la box dans l'application athlète.\n5. Crée tes premiers **Groupes** (Communauté → Groupes) si tu programmes différemment selon les créneaux ou les niveaux : ils servent ensuite à cibler les WODs.\n\n## Erreurs fréquentes\n\n- **Un coach dit qu'il ne voit pas les Programmes athlètes.** C'est volontaire : la page fixe des prix, elle est réservée au gérant → passe par ton propre compte owner.\n- **Un membre ne trouve pas la box dans l'app.** Le code d'invitation n'a pas été communiqué ou a été recopié à la main avec une erreur → renvoie-le depuis le Dashboard.\n- **Le logo n'apparaît pas côté athlète.** L'image n'a pas été enregistrée dans Réglages, ou le téléversement a échoué → recharge la page et vérifie que l'aperçu du logo s'affiche.\n\n## Y aller\n\n<GoTo page=\"dashboard\" />\n",
    "programmes-athletes-seances": "---\nslug: programmes-athletes-seances\ntitle: Remplir un programme athlète\nsummary: Écrire les séances d'un programme de coaching, semaine par semaine.\nrole: coach\npages: [programs]\ntags: [programme, seances, coaching, carnet, pdf]\norder: 40\n---\n\n## Avant de commencer\n\nUn **programme athlète** est un suivi vendu ou assigné à un membre : il contient des séances organisées par semaine, indépendantes du Whiteboard de la box. La page est **Business → Programmes athlètes**.\n\n## Étapes\n\n1. Ouvre **Programmes athlètes** et sélectionne le programme à remplir (ou crée-le d'abord, voir le tutoriel sur la vente).\n2. Ouvre son éditeur de séances : les semaines sont numérotées selon la **Durée (semaines)** du programme. <Screenshot src=\"/tutorials/programmes-athletes-seances/1.png\" alt=\"Éditeur de séances d'un programme athlète\" />\n3. Ajoute une séance dans la semaine voulue, puis saisis son contenu comme un WOD : mouvements du catalogue, bloc Musculation, bloc Cardio, notes coach.\n4. Tu peux partir d'un PDF : l'import propose les séances détectées et tu relis la preview avant insertion.\n5. Enregistre. L'athlète qui a accès au programme voit les séances dans son carnet, semaine par semaine.\n\n## Erreurs fréquentes\n\n- **L'athlète ne voit aucune séance.** Le programme n'a pas de séances enregistrées, ou l'accès ne lui a pas été donné → vérifie les deux, l'accès se donne depuis Programmes athlètes.\n- **Les mouvements ne créditent pas de badge.** Ils ont été tapés à la main au lieu d'être choisis dans la liste officielle → réédite les lignes concernées.\n- **Une semaine est inaccessible.** La durée du programme est plus courte que le nombre de semaines que tu veux écrire → augmente la **Durée (semaines)**.\n- **Les séances d'un programme se retrouvent sur le Whiteboard.** Ce sont deux espaces différents : un programme athlète ne se pose pas sur le Whiteboard de la box → passe par une semaine type si tu veux la programmer pour tous.\n\n## Y aller\n\n<GoTo page=\"programs\" />\n",
    "programmes-athletes-vente": "---\nslug: programmes-athletes-vente\ntitle: Vendre un programme ou une formule\nsummary: Créer une offre destinée aux membres : prix, durée, codes promo et accès manuel.\nrole: owner\npages: [programs]\ntags: [vente, prix, formule, abonnement, code promo, stripe]\norder: 41\n---\n\n## Avant de commencer\n\n**Programmes athlètes** (Business → Programmes athlètes) regroupe ce que tu proposes à tes membres : programmes de coaching, formules d'abonnement, drop-in. Pour encaisser en ligne, les paiements doivent être activés pour la box ; la commission plateforme est affichée sur la page.\n\n## Étapes\n\n1. Ouvre **Programmes athlètes**. Si la page t'invite à **activer les paiements pour vendre tes programmes**, fais-le d'abord : sans cela, tu ne peux qu'assigner des accès à la main.\n2. Crée ton offre et choisis sa nature : programme de coaching à **Durée définie**, **Abonnement** mensuel, ou **Drop-in**.\n3. Renseigne le prix, la **Durée (semaines)** ou l'**Engagement** selon le cas, la description, et les **Conditions / mentions** affichées au visiteur avant le paiement. <Screenshot src=\"/tutorials/programmes-athletes-vente/1.png\" alt=\"Formulaire d'une offre : prix, durée, conditions\" />\n4. Coche **Actif (visible pour les athlètes)** quand l'offre est prête : c'est ce qui la fait apparaître sur ta page publique.\n5. Ajoute si tu veux un **Code promo** (remise, durée de la remise pour les abonnements), ou utilise **Donner l'accès à un membre** pour offrir un programme sans paiement en ligne.\n\n## Erreurs fréquentes\n\n- **L'offre n'apparaît pas côté athlète.** Elle n'est pas cochée **Actif (visible pour les athlètes)** → coche la case et recharge la page publique.\n- **Le paiement échoue ou le bouton manque.** Les paiements ne sont pas activés pour la box → active-les depuis la page, puis réessaie.\n- **Un code promo reste sans effet.** Il est expiré, ou sa durée de remise est terminée → vérifie la date d'expiration affichée dans Codes promo.\n- **Un membre a payé mais n'a pas le contenu.** Le programme vendu n'a pas encore de séances → remplis-le, ou donne-lui l'accès à un programme complet.\n\n## Y aller\n\n<GoTo page=\"programs\" />\n",
    "semaines-types": "---\nslug: semaines-types\ntitle: Semaines types\nsummary: Enregistrer une semaine du Whiteboard pour la reposer plus tard, et savoir ce qu'une semaine type n'est pas.\nrole: coach\npages: [whiteboard]\ntags: [semaine type, modele, whiteboard, programmation, reutilisation]\norder: 25\n---\n\n## Avant de commencer\n\nUne **semaine type** est une copie figée d'une semaine du Whiteboard, rangée dans ta box pour être reposée quand tu veux. Elle est interne : elle ne se vend pas et ne s'expose à personne.\n\n## Étapes\n\n1. Sur le Whiteboard, affiche la semaine que tu veux garder comme modèle.\n2. Clique **Enregistrer comme semaine type**, donne-lui un nom parlant (par exemple « Semaine Hybrid – volume »), puis valide. <Screenshot src=\"/tutorials/semaines-types/1.png\" alt=\"Modale Enregistrer comme semaine type\" />\n3. Pour la reposer, place-toi sur la semaine cible et ouvre **Programmation** : la modale liste **Mes semaines types** et les **Programmations Marketplace** auxquelles la box est abonnée.\n4. Choisis la semaine type, la **Semaine cible**, puis l'audience dans **Qui voit ces WOD ?** — sans ce choix, l'application n'est pas possible.\n5. Applique. Les WODs sont recopiés sur les jours de la semaine cible ; les séances qui portent déjà un score ou une complétion ne sont pas touchées par un remplacement.\n\n## Erreurs fréquentes\n\n- **« J'ai enregistré une semaine type, mais mon offre Marketplace est toujours vide. »** « Enregistrer comme semaine type » n'alimente pas une offre : c'est **Copier vers une offre** qui recopie la semaine dans une semaine d'offre → utilise ce bouton depuis le Whiteboard ou depuis la semaine type.\n- **La modale Programmation est vide.** Aucune semaine type n'existe et la box n'est abonnée à aucune programmation → enregistre une semaine, ou abonne-toi dans Entraînement → Marketplace.\n- **Les WODs posés ne sont visibles par personne.** L'audience choisie à l'application était « personne encore » → rouvre les séances et fixe leur audience.\n- **Supprimer une semaine type a-t-il effacé mes semaines ?** Non : les semaines déjà posées sur le Whiteboard restent, seul le modèle disparaît.\n\n## Y aller\n\n<GoTo page=\"whiteboard\" />\n",
    "tournois": "---\nslug: tournois\ntitle: Créer et suivre un tournoi\nsummary: Monter un tournoi interne, inscrire les participants et suivre le classement.\nrole: both\npages: [tournaments]\ntags: [tournoi, classement, participants, elo, animation]\norder: 60\n---\n\n## Avant de commencer\n\nLes **Tournois** (Animation → Tournois) animent la box : une épreuve, des participants, un classement. La page sépare **En cours & à venir** de l'**Historique**.\n\n## Étapes\n\n1. Ouvre **Tournois** et clique **Créer un tournoi**. <Screenshot src=\"/tutorials/tournois/1.png\" alt=\"Liste des tournois de la box\" />\n2. Renseigne le tournoi : nom, date, niveau et format. Le **Statut** affiché dans la liste suit ensuite le cycle de vie de l'épreuve.\n3. Ouvre le tournoi créé pour gérer ses **Participants** : les membres de la box s'ajoutent depuis la fiche.\n4. Le jour J, saisis les résultats depuis la fiche du tournoi : le **Classement** se recalcule au fur et à mesure.\n5. Une fois terminé, le tournoi part dans l'**Historique** et les performances restent visibles pour les athlètes.\n\n## Erreurs fréquentes\n\n- **« Aucun tournoi. »** Rien n'a encore été créé dans cette box → clique Créer un tournoi.\n- **Un membre ne peut pas être inscrit.** Il n'est pas membre actif de la box → vérifie sa fiche dans Membres.\n- **Le classement semble figé.** Tous les résultats ne sont pas saisis → complète les scores manquants depuis la fiche du tournoi.\n- **Un tournoi passé encombre la liste.** Il rejoint l'Historique quand il est terminé → change son statut plutôt que de le supprimer, pour garder les performances.\n\n## Y aller\n\n<GoTo page=\"tournaments\" />\n",
    "visibilite-d-un-wod": "---\nslug: visibilite-d-un-wod\ntitle: Visibilité d'un WOD\nsummary: Comprendre « Toute la box », « Ces groupes » et « Personne encore », et savoir qui verra la séance.\nrole: both\npages: [whiteboard]\ntags: [visibilite, audience, groupes, personne encore, whiteboard]\norder: 21\n---\n\n## Avant de commencer\n\nChaque WOD porte une audience, réglée dans le bloc **Qui reçoit ce WOD ?** de l'éditeur. C'est le seul élément qui décide de ce qu'un membre voit dans son application.\n\n## Étapes\n\n1. Sur le Whiteboard, ouvre le WOD concerné et descends jusqu'à **Qui reçoit ce WOD ?**. <Screenshot src=\"/tutorials/visibilite-d-un-wod/1.png\" alt=\"Bloc Qui reçoit ce WOD ? avec les trois choix d'audience\" />\n2. Choisis **Toute la box** pour la programmation commune : tous les membres actifs voient la séance à l'heure indiquée.\n3. Choisis **Ces groupes** puis coche les groupes visés pour une séance réservée à un niveau, un créneau ou un programme.\n4. Garde **Personne encore** pour un brouillon : la séance reste visible de toi seul dans le back-office.\n5. Enregistre. La carte du Whiteboard rappelle l'audience choisie — vérifie-la d'un coup d'œil avant le début du cours.\n\n## Erreurs fréquentes\n\n- **« Mes athlètes ne voient rien alors que le WOD est là. »** Le WOD est en « Personne encore » : aucun membre ne le voit, jamais → change l'audience.\n- **Les semaines reçues de la Marketplace n'apparaissent pas côté athlète.** Les poses automatiques du cron arrivent en « Personne encore » : c'est volontaire, à toi de dire qui les reçoit → ouvre chaque séance reçue et choisis son audience.\n- **Un membre du groupe ne voit toujours pas la séance.** Il n'est pas dans le groupe coché, ou n'est plus membre actif → vérifie sa fiche dans Membres.\n- **La séance apparaît en retard.** L'heure du WOD est l'heure de publication → avance-la si tu veux que les athlètes l'aient le matin.\n\n## Y aller\n\n<GoTo page=\"whiteboard\" />\n",
  },
  en: {
    "blocs-force-musculation-cardio": "---\nslug: blocs-force-musculation-cardio\ntitle: Strength and cardio blocks\nsummary: Add strength sets and cardio sets to a WOD, and know what counts towards badges.\nrole: coach\npages: [whiteboard]\ntags: [strength, musculation, cardio, sets, badges, wod]\norder: 22\n---\n\n## Before you start\n\nThe WOD editor has three areas: **Programme / Mouvements** (the metcon), **Musculation** (strength, optional) and **Cardio** (optional). Both optional blocks are written as sets, not as free reps.\n\n## Steps\n\n1. Open a WOD on the Whiteboard and find the **Musculation (optionnel)** block.\n2. Click **Ajouter une série**, then fill in the exercise, sets, reps and load — in kilos, as **%1RM**, or as a free note such as `RPE 9` when the load depends on the day. A **Tempo** (`30X1`) and a rest value can complete the line. <Screenshot src=\"/tutorials/blocs-force-musculation-cardio/1.png\" alt=\"Strength block with one set, load and tempo\" />\n3. Scroll to the **Cardio (optionnel)** block and click **Ajouter une série cardio**: pick the movement (Row, SkiErg, Run and so on), the number of sets and the quantity in metres or calories.\n4. Add an intensity target if you want one: watts **or** pace, never both on the same line. Rest between sets is written as `mm:ss`.\n5. Publish the WOD: the three blocks reach the athlete app together, in the order you wrote them.\n\n## Common mistakes\n\n- **Strength sets credit no badge.** That is the expected behaviour: sets in the strength block do not count badge reps, they are not metcon → put whatever must count in the metcon.\n- **A cardio set is not credited.** The cardio block *is* credited, as `sets × quantity`, but only when the movement comes from the catalogue → pick Row, SkiErg, Run and so on from the list.\n- **A pace target is ignored.** Both watts and a pace were entered on the same line → keep only one of them.\n- **An \"RPE 9\" load disappears from the kilos field.** A non-numeric load is not a weight: it belongs in the load note → use the free note field.\n\n## Go there\n\n<GoTo page=\"whiteboard\" />\n",
    "creer-un-wod": "---\nslug: creer-un-wod\ntitle: Create a WOD\nsummary: Program a session on the Whiteboard: title, date, movements, loads, then publish.\nrole: coach\npages: [whiteboard]\ntags: [wod, whiteboard, movements, loads, programming]\norder: 20\n---\n\n## Before you start\n\nThe **Whiteboard** shows the current week, one column per day. A WOD belongs to a day and a publication time, so you can prepare it in advance without it being visible. On-screen labels are in French and quoted as they appear.\n\n## Steps\n\n1. On the Whiteboard, move to the right week with the arrows or **Aller à une date**, then click **Nouveau WOD** (or click straight into an empty day cell). <Screenshot src=\"/tutorials/creer-un-wod/1.png\" alt=\"Weekly Whiteboard with the new WOD button\" />\n2. Fill in the header: **Titre** (for example \"Fran\", \"Hybrid intervals\"), **Date**, **Heure**, plus **Type** and **Block** if you use those markers. The time you enter is when the WOD becomes visible on the programmed day.\n3. Under **Programme / Mouvements**, add one line per movement: reps, exercise picked from the official list, then men's and women's loads. Picking the exercise from the list is what guarantees your athletes' movement badges are counted.\n4. Add session notes in **Notes Coach** (scaling, cues) and a demo **Vidéo YouTube** if useful. <Screenshot src=\"/tutorials/creer-un-wod/2.png\" alt=\"WOD editor: title, movements and loads\" />\n5. Pick the audience under **Qui reçoit ce WOD ?**: the whole box, selected groups, or nobody yet.\n6. Click **Publier**. The WOD appears in the day cell; clicking the card reopens it for editing.\n\n## Common mistakes\n\n- **The WOD exists but no athlete sees it.** The audience is still \"Personne encore\" (nobody yet) → reopen the WOD and pick the whole box or the relevant groups.\n- **Cannot save with \"Ces groupes\".** No group is ticked and the editor shows \"Coche au moins un groupe.\" → tick the groups, or switch back to the whole box.\n- **Athlete badges do not move after the session.** The movement was typed freely instead of picked from the list → edit the line and select the catalogue exercise.\n- **The edit pencil on a card is inactive.** That session comes from a Marketplace programming: its content cannot be edited, only its audience.\n\n## Go there\n\n<GoTo page=\"whiteboard\" />\n",
    "creneaux-et-reservations": "---\nslug: creneaux-et-reservations\ntitle: Classes and bookings\nsummary: Create the week's classes, set capacity and take attendance.\nrole: owner\npages: [schedule]\ntags: [classes, schedule, bookings, capacity, attendance, coach]\norder: 32\n---\n\n## Before you start\n\n**Horaires & Créneaux** holds the bookable classes of the box, day by day. Recurring weekly grids live next door, in the schedule templates page.\n\n## Steps\n\n1. Open **Horaires & Créneaux** and move to the day you need.\n2. Add a class and fill it in: **Type de cours** (class type) or a custom name, start time, duration, **Capacité** and an optional description. <Screenshot src=\"/tutorials/creneaux-et-reservations/1.png\" alt=\"Class creation form\" />\n3. Assign a coach (optional): they appear on the athlete side and it helps your coaches find their classes.\n4. Save: the class becomes bookable by members, up to its capacity.\n5. On the day, open the class and click **Faire l'appel** to see who booked and mark attendance. You can also add a member by hand if somebody shows up without a booking.\n\n## Common mistakes\n\n- **\"Aucun coach assigné à cette box.\" (no coach in this box).** No coach is registered in the settings → add one, then come back and assign the class.\n- **A member cannot book.** Capacity is full, or the class is in the past → raise the capacity or open a second class.\n- **\"Aucun inscrit pour ce créneau\" although the class is full.** You are looking at another day or another class of the same type → check the date shown at the top.\n- **Next week's classes are missing.** They are generated from the schedule templates → open that page to lay out the recurring grid.\n\n## Go there\n\n<GoTo page=\"schedule\" />\n",
    "groupes-de-membres": "---\nslug: groupes-de-membres\ntitle: Member groups\nsummary: Create groups and add members to target programming and classes.\nrole: owner\npages: [members, groups]\ntags: [groups, members, targeting, audience]\norder: 30\n---\n\n## Before you start\n\nA group gathers members (a level, a time slot, a specific follow-up). It is used as a WOD audience and as a filter in the member list. Groups are managed under **Groupes**.\n\n## Steps\n\n1. Open **Groupes** and create a new group: give it a name a busy coach will understand (\"Competitors\", \"Lunch\", \"Beginners\"). <Screenshot src=\"/tutorials/groupes-de-membres/1.png\" alt=\"Box group list\" />\n2. Save, then open the group to **Ajouter un membre** (add a member); the search covers the active members of the box.\n3. Go to **Membres** to check the result: the group filter lets you display one group at a time.\n4. Then use the group as an audience: in a WOD, choose **Ces groupes** and tick it.\n\n## Common mistakes\n\n- **\"Aucun groupe. Crée des groupes de cours d'abord.\"** The audience selector stays empty until a group exists → create one under Groupes.\n- **A member does not receive the group's WODs.** They were never added to the group, or their account is no longer active → check their member record.\n- **A deleted group leaves WODs with no audience.** Sessions targeted at that group reach nobody → reopen them and pick another audience.\n\n## Go there\n\n<GoTo page=\"groups\" />\n",
    "importer-un-pdf-de-programmation": "---\nslug: importer-un-pdf-de-programmation\ntitle: Import a programming PDF\nsummary: Turn a weekly PDF into WODs or program sessions, reviewing the preview screen first.\nrole: coach\npages: [whiteboard, programs]\ntags: [pdf, import, programming, preview, coach notes]\norder: 24\n---\n\n## Before you start\n\nThe PDF import reads a programming document and proposes ready-to-insert sessions: on the **Whiteboard** for the box week, or in the session editor of an athlete program. The analysis is a proposal, never a direct save.\n\n## Steps\n\n1. From the Whiteboard, open the import and drop your file — you can also drag it onto the page, which shows \"Lâche ton fichier pour l'importer\".\n2. Wait for the analysis to finish. The preview screen lists every detected session with its movements, its **Musculation** block and its **Notes coach**. <Screenshot src=\"/tutorials/importer-un-pdf-de-programmation/1.png\" alt=\"PDF import preview with the detected sessions\" />\n3. Review it line by line. Highlighted fields carry the warning \"Mouvement hors catalogue\" (movement out of catalogue): fix them by picking the exercise from the list, or knowingly keep the raw name.\n4. Pick the audience under **Qui verra ces WOD** (or **Qui verra ces séances** for an athlete program): the whole box, some groups, or nobody for now.\n5. Confirm the insertion. Sessions land on the detected days and stay editable like any other WOD.\n\n## Common mistakes\n\n- **\"Aucun WOD détecté dans ce PDF.\" (no WOD detected).** The document is a scanned image or a layout the analysis does not recognise → type the week in by hand, or use a text PDF.\n- **RPE or percentage-of-RM loads vanished from the weight fields.** A non-numeric load is not a kilo: it becomes a load note or coach notes → check it in the preview before inserting.\n- **Some movements are highlighted in orange.** They are out of catalogue and will be kept as is, so without badges → replace them with a list entry.\n- **Imported sessions are visible to nobody.** The audience chosen in the preview was \"nobody yet\" → reopen each session and set its audience.\n\n## Go there\n\n<GoTo page=\"whiteboard\" />\n",
    "marketplace-appliquer-au-whiteboard": "---\nslug: marketplace-appliquer-au-whiteboard\ntitle: Apply a programming to the Whiteboard\nsummary: Place a week from a subscribed programming, understand week anchoring, and know what stays editable.\nrole: both\npages: [whiteboard]\ntags: [marketplace, programming, whiteboard, anchoring, cron, audience]\norder: 51\n---\n\n## Before you start\n\nOnce the box subscribes, the weeks of a programming are placed on the Whiteboard: automatically if you asked for it, otherwise by hand from the **Programmation** button.\n\n## Steps\n\n1. On the Whiteboard, click **Programmation**. The dialog lists **Mes semaines types** (your week templates) then **Programmations Marketplace** with your active subscriptions (offer, publishing box, number of WODs and weeks). <Screenshot src=\"/tutorials/marketplace-appliquer-au-whiteboard/1.png\" alt=\"Programmation dialog with a Marketplace subscription selected\" />\n2. Select the subscription to place: it gets highlighted and the placement fields appear.\n3. Pick the **Semaine source** (the programming week, with its number of WODs) and the **Semaine cible** (the Monday the sessions start from). The dialog restates the exact date used.\n4. Pick the audience under **Qui voit ces WOD ?**: **Toute la box** (whole box), **Ces groupes** (these groups) or **Personne encore** (nobody yet). That choice also becomes the default visibility of this subscription's automatic placement.\n5. Click **Appliquer**. Sessions land on the days of the target week, in the subscription colour; those that already carry a score or a completion are not replaced.\n6. Then adjust card by card: the audience remains yours, and a received session can be moved or deleted individually.\n\n## Common mistakes\n\n- **Automatic weeks do not arrive when expected.** With automatic placement, the due week is placed on Sunday at 18:00 for the week that follows; placing a week by hand realigns the anchor on what you have just done. {/* TODO Nab: vérifier libellé — la spec parle du lundi suivant l'abonnement, l'écran Marketplace annonce le dimanche 18h */}\n- **A received session refuses to be edited.** Its content belongs to the programming and is not editable. You can delete it, card by card, or change its audience.\n- **Nobody sees the placed sessions.** The audience stayed on \"nobody yet\", which is the default for automatic placements → set the audience.\n- **The dialog offers no programming.** `Programmations Marketplace` shows `Aucun abonnement actif` (no active subscription) → go through the Marketplace.\n- **Placing a week template is not a Marketplace offer.** The top of the dialog (`Mes semaines types`) places your own templates; it creates neither a subscription nor a published offer.\n\n## Go there\n\n<GoTo page=\"whiteboard\" />\n",
    "marketplace-publier-une-offre": "---\nslug: marketplace-publier-une-offre\ntitle: Publish an offer on the Marketplace\nsummary: Create a programming, fill it week by week, and publish it in the catalogue.\nrole: owner\npages: [marketplace, whiteboard]\ntags: [marketplace, offer, publishing, selling, weeks]\norder: 52\n---\n\n## Before you start\n\nPublishing an offer means proposing your programming to other boxes. The **Mes offres** tab of the Marketplace holds your published and draft programmings.\n\n## Steps\n\n1. Open the **Marketplace**, tab **Mes offres**, and create a programming: title, description, goal, target audience, discipline, level, WODs per week and billing. <Screenshot src=\"/tutorials/marketplace-publier-une-offre/1.png\" alt=\"My offers tab of the Marketplace\" />\n2. Fill in its weeks. The fastest route: from the Whiteboard, display a week that worked and click **Copier vers une offre**, then pick the offer and the week number.\n3. Check the content week by week. The screen flags an offer whose week 1 is empty.\n4. Click the publish control on the offer: it joins the **Catalogue** and becomes visible to other boxes.\n5. If you run several boxes, you can also broadcast it to your own boxes, unticking those you want to exclude.\n\n## Common mistakes\n\n- **\"Publication refusée\" (publishing refused).** An offer with no WOD cannot be published and never appears in the catalogue → fill at least week 1, then publish again.\n- **\"I saved a week template and the offer stayed empty.\"** A week template is internal to your box: it does not populate an offer → use **Copier vers une offre**.\n- **Subscribed boxes do not see my correction.** Copies are independent: editing an offer week does not rewrite what has already been received → warn your subscribers, or fix the next week.\n- **My offer is missing from my own catalogue.** That is intended: you cannot subscribe to your own offers → review it from the \"Mes offres\" tab.\n\n## Go there\n\n<GoTo page=\"marketplace\" />\n",
    "marketplace-s-abonner-a-une-programmation": "---\nslug: marketplace-s-abonner-a-une-programmation\ntitle: Subscribe to a Marketplace programming\nsummary: Find a programming published by another box, subscribe, and set automatic weekly placement.\nrole: owner\npages: [marketplace, whiteboard]\ntags: [marketplace, subscription, programming, catalogue, automatic placement]\norder: 50\n---\n\n## Before you start\n\nThe **Marketplace** is the box-to-box channel: you buy or sell programmings there. What you receive lands on your Whiteboard.\n\n## Steps\n\n1. Open the **Marketplace**, tab **Catalogue**, and filter by discipline, level or **Gratuit** (free) to browse the offers published by other boxes. Each card shows the publishing box, the goal, the number of WODs and the duration. <Screenshot src=\"/tutorials/marketplace-s-abonner-a-une-programmation/1.png\" alt=\"Marketplace catalogue with filters and one offer\" />\n2. Click **Voir le détail** (see details): you get the goal, the target audience, the equipment, the WODs per week, the billing (monthly, one-off or free) and the day-by-day preview of week 1. <Screenshot src=\"/tutorials/marketplace-s-abonner-a-une-programmation/2.png\" alt=\"Marketplace offer details with the week 1 preview\" />\n3. Click **S'abonner** (subscribe). The button becomes **Abonné** (subscribed) and the card shows the subscription settings. Your own offers are never offered for subscription.\n4. Pick the **Couleur** (colour): it is what identifies the sessions of this programming on the Whiteboard. <Screenshot src=\"/tutorials/marketplace-s-abonner-a-une-programmation/3.png\" alt=\"Subscribed offer with colour, automatic placement and unsubscribe link\" />\n5. Decide how weeks are placed. Nothing is placed on its own until **Application automatique chaque semaine** is ticked; once ticked, the due week is placed by itself on Sunday at 18:00, week 1 on the first Sunday. Unticked, you place weeks whenever you want from the Whiteboard, using the **Programmation** button.\n6. To stop, use **Se désabonner** (unsubscribe) on the same card: a confirmation offers to also remove the sessions already placed from next week on. The current week and the past are never deleted, so scores and ELO are kept.\n\n## Common mistakes\n\n- **Nothing arrives on the Whiteboard after subscribing.** Automatic placement is unticked — that is the default → place the week from the Whiteboard, or tick the box.\n- **Received sessions are seen by no member.** Automatic placements arrive as \"Personne encore\" (nobody yet) → open them and set their audience.\n- **A received session cannot be edited.** The content of a Marketplace programming is not editable; you only choose who sees it, and you may move or delete it.\n- **\"déjà abonnée\" (already subscribed).** Another of your boxes already subscribes to this offer → check the active box in the sidebar selector.\n\n## Go there\n\n<GoTo page=\"marketplace\" />\n",
    "membres-et-formules": "---\nslug: membres-et-formules\ntitle: Members, contracts and plans\nsummary: Track the members of your box, their contracts and their access to your offers.\nrole: owner\npages: [members]\ntags: [members, contracts, subscriptions, plans, invitation]\norder: 31\n---\n\n## Before you start\n\nMembers join the box with the invitation code from the Dashboard. The **Membres** page then lists everybody, with search, filters and access to contracts.\n\n## Steps\n\n1. Open **Membres**: the counter at the top shows how many records are displayed out of the total, and the search accepts a name or an email. <Screenshot src=\"/tutorials/membres-et-formules/1.png\" alt=\"Member list with search and filters\" />\n2. Narrow it down with the filters: by group, or by contract state, to find for instance members without a subscription.\n3. Click **Contrats** to show the **Contrats / Abonnements** column: you see at a glance which plan each member holds and until when.\n4. Open a member record for the detail: groups, ELO, history. This is also where you check that a member is active.\n5. The plans themselves (price, duration, commitment) are created in the athlete programs page: the member list consumes them, it does not define them.\n\n## Common mistakes\n\n- **A member is missing from the list.** They have not joined the box with the invitation code yet → send them the code from the Dashboard.\n- **A member says they paid but has no contract.** The payment happened outside AthleX, or the checkout never completed → check the contracts column and, if needed, grant access from the athlete programs page.\n- **You cannot create a plan from the member list.** That is expected: creating and editing plans lives in the athlete programs page → open it there.\n- **A coach cannot see the member list.** It is owner-only → sign in with the owner account.\n\n## Go there\n\n<GoTo page=\"members\" />\n",
    "mouvements-et-badges": "---\nslug: mouvements-et-badges\ntitle: Movements and badges\nsummary: Why exercises must be picked from the official list, and what credits athlete badges.\nrole: coach\npages: [whiteboard]\ntags: [movements, catalogue, badges, reps, whiteboard]\norder: 23\n---\n\n## Before you start\n\nAthlete movement badges are computed from completed reps, movement by movement. The link is made through the official catalogue offered in the WOD editor, not from the text you type.\n\n## Steps\n\n1. In a WOD, go to a line of **Programme / Mouvements** and start typing in the exercise field: the list filters as you type. <Screenshot src=\"/tutorials/mouvements-et-badges/1.png\" alt=\"Searching a movement in the official list\" />\n2. Select the suggested entry even if its name differs slightly from your habit — that choice is what links the line to the movement tracked by the app.\n3. Enter the reps and the men's / women's loads: the badge is computed from reps, the loads serve the athlete and the ranking.\n4. Repeat for every metcon line, then publish. After the session, the reps validated by athletes feed their badges with no further action from you.\n\n## Common mistakes\n\n- **A hand-typed movement gives no badge.** Out of catalogue, it is stored with its raw name and credits nothing → edit the line and take the list entry.\n- **Strength block reps do not count.** Strength sets are not metcon: they credit no badge, unlike the cardio block, which is credited as `sets × quantity`.\n- **A movement is missing from the list.** The catalogue is shared platform-wide and cannot be edited from the box → write it in plain text for the session and report it to AthleX so it can be added.\n- **Two variants of the same movement give different counters.** They are two distinct catalogue entries → keep the same entry from one session to the next.\n\n## Go there\n\n<GoTo page=\"whiteboard\" />\n",
    "premiers-pas": "---\nslug: premiers-pas\ntitle: Getting started with AthleX Manager\nsummary: What to set up on day one so the box runs: identity, coaches, invitation code.\nrole: both\npages: [dashboard]\ntags: [getting started, dashboard, settings, invitation, coach]\norder: 10\n---\n\n## Before you start\n\nYou have just created your box. The Dashboard is the back-office home page, and the sidebar groups sections by role (training, community, events, business). Allow five minutes for this setup. On-screen labels are in French, so they are quoted as they appear.\n\n## Steps\n\n1. Open the **Dashboard**: the counters at the top (members, bookings, tournaments, unread messages) are shortcuts, not just numbers — clicking one opens the matching section. <Screenshot src=\"/tutorials/premiers-pas/1.png\" alt=\"Dashboard with the box counters\" />\n2. Go to **Réglages** (Settings) and fill in **Informations de la box**: name, logo, banner. These are what your members and public page visitors see.\n3. Still in **Réglages**, add your **Coachs**. A coach sees the Whiteboard, schedules, schedule templates, messages and the Help tab; a coach never sees prices or subscribers.\n4. Copy the invitation code from the Dashboard and send it to your members: that is how they join the box in the athlete app.\n5. Create your first groups (Groupes) if you program differently per time slot or level: groups are then used to target WODs.\n\n## Common mistakes\n\n- **A coach says the athlete programs page is missing.** That is intended: the page sets prices and is owner-only → use your own owner account.\n- **A member cannot find the box in the app.** The invitation code was never sent, or was retyped with a typo → send it again from the Dashboard.\n- **The logo does not show on the athlete side.** The image was not saved in Réglages, or the upload failed → reload the page and check that the logo preview appears.\n\n## Go there\n\n<GoTo page=\"dashboard\" />\n",
    "programmes-athletes-seances": "---\nslug: programmes-athletes-seances\ntitle: Fill in an athlete program\nsummary: Write the sessions of a coaching program, week by week.\nrole: coach\npages: [programs]\ntags: [program, sessions, coaching, logbook, pdf]\norder: 40\n---\n\n## Before you start\n\nAn athlete program is a follow-up sold or granted to a member: it holds sessions organised by week, independent from the box Whiteboard. The page is **Programmes athlètes**.\n\n## Steps\n\n1. Open **Programmes athlètes** and select the program to fill in (or create it first, see the selling tutorial).\n2. Open its session editor: weeks are numbered according to the program duration in weeks. <Screenshot src=\"/tutorials/programmes-athletes-seances/1.png\" alt=\"Session editor of an athlete program\" />\n3. Add a session to the week you want, then write its content like a WOD: catalogue movements, strength block, cardio block, coach notes.\n4. You can start from a PDF: the import proposes the detected sessions and you review the preview before inserting.\n5. Save. The athlete who has access to the program sees the sessions in their logbook, week by week.\n\n## Common mistakes\n\n- **The athlete sees no session.** The program has no saved sessions, or access was never granted → check both; access is granted from the athlete programs page.\n- **Movements credit no badge.** They were typed by hand instead of picked from the official list → edit the lines concerned.\n- **A week is unreachable.** The program duration is shorter than the number of weeks you want to write → increase the duration in weeks.\n- **Program sessions end up on the Whiteboard.** These are two separate spaces: an athlete program is never placed on the box Whiteboard → use a week template if you want to program it for everybody.\n\n## Go there\n\n<GoTo page=\"programs\" />\n",
    "programmes-athletes-vente": "---\nslug: programmes-athletes-vente\ntitle: Sell a program or a plan\nsummary: Create an offer for your members: price, duration, promo codes and manual access.\nrole: owner\npages: [programs]\ntags: [selling, price, plan, subscription, promo code, stripe]\norder: 41\n---\n\n## Before you start\n\n**Programmes athlètes** gathers what you offer your members: coaching programs, subscription plans, drop-ins. To take payments online, payments must be enabled for the box; the platform commission is displayed on the page.\n\n## Steps\n\n1. Open **Programmes athlètes**. If the page invites you to enable payments in order to sell your programs, do that first: without it you can only grant access by hand.\n2. Create your offer and choose its nature: a fixed-duration coaching program, a monthly subscription, or a drop-in.\n3. Fill in the price, the duration in weeks or the commitment depending on the case, the description, and the terms shown to the visitor before payment. <Screenshot src=\"/tutorials/programmes-athletes-vente/1.png\" alt=\"Offer form: price, duration, terms\" />\n4. Tick **Actif (visible pour les athlètes)** when the offer is ready: that is what makes it appear on your public page.\n5. Optionally add a promo code (discount, and discount duration for subscriptions), or use **Donner l'accès à un membre** to grant a program without an online payment.\n\n## Common mistakes\n\n- **The offer does not appear on the athlete side.** It is not ticked as active and visible → tick the box and reload the public page.\n- **Payment fails, or the button is missing.** Payments are not enabled for the box → enable them from the page, then try again.\n- **A promo code has no effect.** It has expired, or its discount duration is over → check the expiry date shown in the promo codes section.\n- **A member paid but has no content.** The program sold has no sessions yet → fill it in, or grant access to a complete program.\n\n## Go there\n\n<GoTo page=\"programs\" />\n",
    "semaines-types": "---\nslug: semaines-types\ntitle: Week templates\nsummary: Save a Whiteboard week to reuse it later, and learn what a week template is not.\nrole: coach\npages: [whiteboard]\ntags: [week template, model, whiteboard, programming, reuse]\norder: 25\n---\n\n## Before you start\n\nA week template (\"semaine type\") is a frozen copy of a Whiteboard week, stored in your box so you can place it again whenever you want. It is internal: it is never sold and never exposed to anyone.\n\n## Steps\n\n1. On the Whiteboard, display the week you want to keep as a model.\n2. Click **Enregistrer comme semaine type**, give it a meaningful name (for example \"Hybrid week – volume\"), then confirm. <Screenshot src=\"/tutorials/semaines-types/1.png\" alt=\"Save week as template dialog\" />\n3. To place it again, go to the target week and open **Programmation**: the dialog lists **Mes semaines types** (your templates) and the **Programmations Marketplace** your box subscribes to.\n4. Pick the template, the target week, then the audience under **Qui voit ces WOD ?** — without that choice the placement is refused.\n5. Apply. WODs are copied onto the days of the target week; sessions that already carry a score or a completion are never overwritten.\n\n## Common mistakes\n\n- **\"I saved a week template but my Marketplace offer is still empty.\"** \"Enregistrer comme semaine type\" does not populate an offer: **Copier vers une offre** (copy to an offer) is what copies a week into an offer week → use that button.\n- **The Programmation dialog is empty.** No template exists and the box has no subscription → save a week, or subscribe to an offer in the Marketplace.\n- **The placed WODs are visible to nobody.** The audience chosen at placement time was \"nobody yet\" → reopen the sessions and set their audience.\n- **Did deleting a template erase my weeks?** No: weeks already placed on the Whiteboard stay, only the model disappears.\n\n## Go there\n\n<GoTo page=\"whiteboard\" />\n",
    "tournois": "---\nslug: tournois\ntitle: Create and run a tournament\nsummary: Set up an in-box tournament, register participants and follow the ranking.\nrole: both\npages: [tournaments]\ntags: [tournament, ranking, participants, elo, events]\norder: 60\n---\n\n## Before you start\n\n**Tournois** brings the box to life: one event, participants, a ranking. The page separates ongoing and upcoming tournaments from the history.\n\n## Steps\n\n1. Open **Tournois** and create a tournament. <Screenshot src=\"/tutorials/tournois/1.png\" alt=\"Tournament list of the box\" />\n2. Fill it in: name, date, level and format. The status shown in the list then follows the life cycle of the event.\n3. Open the tournament to manage its participants: box members are added from its record.\n4. On the day, enter the results from the tournament record: the ranking recomputes as you go.\n5. Once finished, the tournament moves to the history and the performances stay visible to athletes.\n\n## Common mistakes\n\n- **\"Aucun tournoi.\" (no tournament).** Nothing has been created in this box yet → create one.\n- **A member cannot be registered.** They are not an active member of the box → check their member record.\n- **The ranking looks frozen.** Not all results are entered → complete the missing scores from the tournament record.\n- **A past tournament clutters the list.** It moves to the history once finished → change its status rather than deleting it, so performances are kept.\n\n## Go there\n\n<GoTo page=\"tournaments\" />\n",
    "visibilite-d-un-wod": "---\nslug: visibilite-d-un-wod\ntitle: WOD visibility\nsummary: Understand the whole box, selected groups and \"nobody yet\", and know who will see a session.\nrole: both\npages: [whiteboard]\ntags: [visibility, audience, groups, nobody yet, whiteboard]\norder: 21\n---\n\n## Before you start\n\nEvery WOD carries an audience, set in the **Qui reçoit ce WOD ?** block of the editor. It is the only thing that decides what a member sees in the app.\n\n## Steps\n\n1. On the Whiteboard, open the WOD and scroll to **Qui reçoit ce WOD ?**. <Screenshot src=\"/tutorials/visibilite-d-un-wod/1.png\" alt=\"Audience block with its three options\" />\n2. Pick **Toute la box** (whole box) for shared programming: every active member sees the session at the time you set.\n3. Pick **Ces groupes** (these groups) and tick the groups for a session reserved to one level, time slot or program.\n4. Keep **Personne encore** (nobody yet) for a draft: the session stays visible to you only, in the back-office.\n5. Save. The Whiteboard card shows the chosen audience — check it at a glance before the class starts.\n\n## Common mistakes\n\n- **\"My athletes see nothing although the WOD is there.\"** The WOD is set to \"Personne encore\": no member ever sees it → change the audience.\n- **Weeks received from the Marketplace do not appear on the athlete side.** Automatic placements arrive as \"Personne encore\" by design, so you decide who gets them → open each received session and set its audience.\n- **A member of the group still does not see the session.** They are not in the ticked group, or are no longer an active member → check their member record.\n- **The session shows up late.** The WOD time is the publication time → move it earlier if athletes should have it in the morning.\n\n## Go there\n\n<GoTo page=\"whiteboard\" />\n",
  },
};

